import ast
import io
import re
import subprocess
import sys
import tokenize
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

GENERATED_HEADERS = (
    "// @generated by `flutter_rust_bridge`",
    "# This file tracks properties of this Flutter project.",
    "// !$*UTF8*$!",
)

VENDORED = ("app/rust_builder/",)

SKIP_SUFFIXES = {
    ".md", ".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".ttf", ".otf", ".woff",
    ".woff2", ".ico", ".mp4", ".mp3", ".wav", ".ogg", ".json", ".lock", ".bin", ".der",
    ".pem", ".csv", ".txt", ".jar", ".keystore", ".apk", ".aab", ".zip", ".gz", ".pczt",
    ".xcworkspacedata", ".xcsettings",
}

PROSE = {"LICENSE-APACHE", "LICENSE-MIT", "NOTICE"}


@dataclass(frozen=True)
class Comment:
    start: int
    end: int


class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.n = len(text)
        self.found: list[Comment] = []

    def add(self, start: int, end: int):
        self.found.append(Comment(start, end))

    def line_end(self, i: int) -> int:
        j = self.text.find("\n", i)
        return self.n if j < 0 else j

    def block(self, i: int, nested: bool) -> int:
        start, depth, i = i, 1, i + 2
        while i < self.n and depth:
            if nested and self.text.startswith("/*", i):
                depth, i = depth + 1, i + 2
            elif self.text.startswith("*/", i):
                depth, i = depth - 1, i + 2
            else:
                i += 1
        self.add(start, i)
        return i

    def quoted(self, i: int, quote: str, escapes: bool = True) -> int:
        i += len(quote)
        while i < self.n:
            if escapes and self.text[i] == "\\":
                i += 2
            elif self.text.startswith(quote, i):
                return i + len(quote)
            else:
                i += 1
        return i


class RustLexer(Lexer):
    def run(self) -> list[Comment]:
        t, i = self.text, 0
        while i < self.n:
            c = t[i]
            if t.startswith("//", i):
                j = self.line_end(i)
                self.add(i, j)
                i = j
            elif t.startswith("/*", i):
                i = self.block(i, nested=True)
            elif c == "#" and re.match(r"#!?\[\s*doc\b", t[i:i + 12]):
                j = self.bracket(i + t.index("[", i) - i)
                self.add(i, j)
                i = j
            elif c in "rbc" and not self.ident_before(i) and (m := re.match(r"(?:br|cr|r)(#*)\"", t[i:i + 260])):
                hashes = m.group(1)
                i = t.find('"' + hashes, i + m.end())
                i = self.n if i < 0 else i + 1 + len(hashes)
            elif c in "bc" and not self.ident_before(i) and t.startswith('"', i + 1):
                i = self.quoted(i + 1, '"')
            elif c == '"':
                i = self.quoted(i, '"')
            elif c == "'":
                i = self.char_or_lifetime(i)
            else:
                i += 1
        return self.found

    def ident_before(self, i: int) -> bool:
        return i > 0 and (self.text[i - 1].isalnum() or self.text[i - 1] == "_")

    def bracket(self, i: int) -> int:
        depth = 0
        while i < self.n:
            ch = self.text[i]
            if ch == '"':
                i = self.quoted(i, '"')
                continue
            if ch == "[":
                depth += 1
            elif ch == "]":
                depth -= 1
                if depth == 0:
                    return i + 1
            i += 1
        return i

    def char_or_lifetime(self, i: int) -> int:
        t = self.text
        if t.startswith("\\", i + 1):
            j = i + 2
            while j < self.n and t[j] != "'":
                j += 1
            return j + 1
        if i + 2 < self.n and t[i + 2] == "'":
            return i + 3
        return i + 1


class DartLexer(Lexer):
    def run(self) -> list[Comment]:
        self.code(0, stop_at_brace=False)
        return self.found

    def code(self, i: int, stop_at_brace: bool) -> int:
        t, depth = self.text, 0
        while i < self.n:
            c = t[i]
            if t.startswith("//", i):
                j = self.line_end(i)
                self.add(i, j)
                i = j
            elif t.startswith("/*", i):
                i = self.block(i, nested=True)
            elif c in "'\"":
                raw = i > 0 and t[i - 1] == "r" and not (i > 1 and (t[i - 2].isalnum() or t[i - 2] in "_$"))
                i = self.string(i, raw)
            elif c == "{":
                depth += 1
                i += 1
            elif c == "}":
                if stop_at_brace and depth == 0:
                    return i + 1
                depth -= 1
                i += 1
            else:
                i += 1
        return i

    def string(self, i: int, raw: bool) -> int:
        t = self.text
        quote = t[i] * 3 if t.startswith(t[i] * 3, i) else t[i]
        i += len(quote)
        while i < self.n:
            if not raw and t[i] == "\\":
                i += 2
            elif not raw and t.startswith("${", i):
                i = self.code(i + 2, stop_at_brace=True)
            elif t.startswith(quote, i):
                return i + len(quote)
            elif len(quote) == 1 and t[i] == "\n":
                return i
            else:
                i += 1
        return i


REGEX_BEFORE = set("(,=:[!&|?{};+-*%<>~^") | {""}
REGEX_KEYWORDS = {"return", "typeof", "case", "do", "else", "in", "of", "new", "delete", "void", "throw", "yield", "await"}


class ScriptLexer(Lexer):
    def __init__(self, text: str, jsx: bool = False, nested: bool = False):
        super().__init__(text)
        self.jsx = jsx
        self.nested = nested

    def run(self) -> list[Comment]:
        self.code(0, stop_at_brace=False)
        return self.found

    def prev_token(self, i: int) -> str:
        j = i - 1
        while j >= 0 and self.text[j] in " \t\r\n":
            j -= 1
        if j < 0:
            return ""
        if self.text[j].isalnum() or self.text[j] in "_$":
            k = j
            while k >= 0 and (self.text[k].isalnum() or self.text[k] in "_$"):
                k -= 1
            return self.text[k + 1:j + 1]
        return self.text[j]

    def regex_allowed(self, i: int) -> bool:
        p = self.prev_token(i)
        return p in REGEX_BEFORE or p in REGEX_KEYWORDS

    def code(self, i: int, stop_at_brace: bool) -> int:
        t, depth = self.text, 0
        while i < self.n:
            c = t[i]
            if t.startswith("//", i):
                j = self.line_end(i)
                self.add(i, j)
                i = j
            elif t.startswith("/*", i):
                i = self.block(i, nested=self.nested)
            elif c in "'\"":
                i = self.quoted(i, c)
            elif c == "`":
                i = self.template(i)
            elif c == "/" and self.regex_allowed(i):
                i = self.regex(i)
            elif self.jsx and c == "<" and self.jsx_start(i):
                i = self.jsx_element(i)
            elif c == "{":
                depth += 1
                i += 1
            elif c == "}":
                if stop_at_brace and depth == 0:
                    return i + 1
                depth -= 1
                i += 1
            else:
                i += 1
        return i

    def template(self, i: int) -> int:
        t, i = self.text, i + 1
        while i < self.n:
            if t[i] == "\\":
                i += 2
            elif t.startswith("${", i):
                i = self.code(i + 2, stop_at_brace=True)
            elif t[i] == "`":
                return i + 1
            else:
                i += 1
        return i

    def regex(self, i: int) -> int:
        t, i, cls = self.text, i + 1, False
        while i < self.n and t[i] != "\n":
            if t[i] == "\\":
                i += 2
                continue
            if t[i] == "[":
                cls = True
            elif t[i] == "]":
                cls = False
            elif t[i] == "/" and not cls:
                return i + 1
            i += 1
        return i

    def jsx_start(self, i: int) -> bool:
        p = self.prev_token(i)
        nxt = self.text[i + 1:i + 2]
        return (p in REGEX_BEFORE or p in REGEX_KEYWORDS or p == ">" or p == ")") and (nxt.isalpha() or nxt == ">")

    def jsx_element(self, i: int) -> int:
        t = self.text
        i = self.jsx_tag(i)
        if t[i - 2:i] == "/>":
            return i
        depth = 1
        while i < self.n and depth:
            if t.startswith("{", i):
                i = self.code(i + 1, stop_at_brace=True)
            elif t.startswith("</", i):
                i = self.jsx_tag(i)
                depth -= 1
            elif t[i] == "<" and (t[i + 1:i + 2].isalpha() or t[i + 1:i + 2] == ">"):
                i = self.jsx_tag(i)
                if t[i - 2:i] != "/>":
                    depth += 1
            else:
                i += 1
        return i

    def jsx_tag(self, i: int) -> int:
        t, i = self.text, i + 1
        while i < self.n and t[i] != ">":
            if t[i] in "'\"":
                i = self.quoted(i, t[i], escapes=False)
            elif t[i] == "{":
                i = self.code(i + 1, stop_at_brace=True)
            else:
                i += 1
        return i + 1


class CssLexer(Lexer):
    def run(self) -> list[Comment]:
        t, i = self.text, 0
        while i < self.n:
            if t.startswith("/*", i):
                i = self.block(i, nested=False)
            elif t[i] in "'\"":
                i = self.quoted(i, t[i])
            else:
                i += 1
        return self.found


class MarkupLexer(Lexer):
    def run(self) -> list[Comment]:
        t, i = self.text, 0
        while i < self.n:
            j = t.find("<!--", i)
            if j < 0:
                break
            k = t.find("-->", j + 4)
            k = self.n if k < 0 else k + 3
            self.add(j, k)
            i = k
        return self.found


class AstroLexer(Lexer):
    def run(self) -> list[Comment]:
        t, i = self.text, 0
        if t.startswith("---"):
            end = t.find("\n---", 3)
            end = self.n if end < 0 else end
            self.merge(ScriptLexer(t[3:end]).run(), 3)
            i = end + 4
        while i < self.n:
            if t.startswith("<!--", i):
                k = t.find("-->", i + 4)
                k = self.n if k < 0 else k + 3
                self.add(i, k)
                i = k
            elif m := re.match(r"<(script|style)\b[^>]*>", t[i:i + 400]):
                body = i + m.end()
                close = t.find(f"</{m.group(1)}>", body)
                close = self.n if close < 0 else close
                sub = ScriptLexer(t[body:close]) if m.group(1) == "script" else CssLexer(t[body:close])
                self.merge(sub.run(), body)
                i = close
            elif t[i] == "{":
                end = self.expression(i)
                i = end
            elif t[i] == "<":
                i = self.tag(i)
            else:
                i += 1
        return self.found

    def expression(self, i: int) -> int:
        lexer = ScriptLexer(self.text, jsx=True)
        end = lexer.code(i + 1, stop_at_brace=True)
        self.found.extend(lexer.found)
        return end

    def tag(self, i: int) -> int:
        t, i = self.text, i + 1
        while i < self.n and t[i] != ">":
            if t[i] in "'\"":
                i = self.quoted(i, t[i], escapes=False)
            elif t[i] == "{":
                i = self.expression(i)
            else:
                i += 1
        return i + 1

    def merge(self, found: list[Comment], offset: int):
        self.found.extend(Comment(c.start + offset, c.end + offset) for c in found)


class PythonLexer(Lexer):
    def run(self) -> list[Comment]:
        lines = self.text.splitlines(keepends=True)
        starts = [0]
        for line in lines:
            starts.append(starts[-1] + len(line))

        def offset(row: int, col: int) -> int:
            return starts[row - 1] + len(lines[row - 1][:col].encode("utf-8").decode("utf-8"))

        for tok in tokenize.generate_tokens(io.StringIO(self.text).readline):
            if tok.type == tokenize.COMMENT and not (tok.start[0] == 1 and tok.string.startswith("#!")):
                self.add(offset(*tok.start), offset(*tok.end))
        for node in ast.walk(ast.parse(self.text)):
            if isinstance(node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)) and node.body:
                first = node.body[0]
                if isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant) and isinstance(first.value.value, str):
                    self.add(offset(first.lineno, first.col_offset), offset(first.end_lineno, first.end_col_offset))
        return self.found


class ShellLexer(Lexer):
    def run(self) -> list[Comment]:
        t, i, heredocs = self.text, 0, []
        while i < self.n:
            c = t[i]
            if c == "\n" and heredocs:
                i = self.skip_heredocs(i + 1, heredocs)
                heredocs = []
            elif c == "\\":
                i += 2
            elif c == "'":
                j = t.find("'", i + 1)
                i = self.n if j < 0 else j + 1
            elif c == '"':
                i = self.double(i)
            elif c == "$" and t.startswith("${", i):
                i = self.braced(i + 2)
            elif c == "$" and t.startswith("$#", i):
                i += 2
            elif c == "#" and (i == 0 or t[i - 1] in " \t\n;&|()"):
                if i == 0 and t.startswith("#!"):
                    i = self.line_end(i)
                    continue
                j = self.line_end(i)
                self.add(i, j)
                i = j
            elif m := re.match(r"<<(-?)\s*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\2", t[i:i + 80]):
                heredocs.append((m.group(3), m.group(1) == "-"))
                i += m.end()
            else:
                i += 1
        return self.found

    def double(self, i: int) -> int:
        t, i = self.text, i + 1
        while i < self.n:
            if t[i] == "\\":
                i += 2
            elif t[i] == '"':
                return i + 1
            elif t.startswith("$(", i):
                i = self.subshell(i + 2)
            elif t.startswith("${", i):
                i = self.braced(i + 2)
            else:
                i += 1
        return i

    def subshell(self, i: int) -> int:
        t, depth = self.text, 1
        while i < self.n and depth:
            if t[i] == "\\":
                i += 2
                continue
            if t[i] == "'":
                j = t.find("'", i + 1)
                i = self.n if j < 0 else j + 1
                continue
            if t[i] == '"':
                i = self.double(i)
                continue
            if t[i] == "(":
                depth += 1
            elif t[i] == ")":
                depth -= 1
            i += 1
        return i

    def braced(self, i: int) -> int:
        t, depth = self.text, 1
        while i < self.n and depth:
            if t[i] == "{":
                depth += 1
            elif t[i] == "}":
                depth -= 1
            i += 1
        return i

    def skip_heredocs(self, i: int, heredocs: list[tuple[str, bool]]) -> int:
        for word, tabs in heredocs:
            while i < self.n:
                end = self.line_end(i)
                line = self.text[i:end]
                i = end + 1
                if (line.lstrip("\t") if tabs else line) == word:
                    break
        return i


def hash_line(lexer: Lexer, i: int, end: int, line_start_only: bool):
    t = lexer.text
    stripped = t[i:end].lstrip()
    if stripped.startswith("#"):
        lexer.add(end - len(stripped), end)
        return
    if line_start_only:
        return
    j, quote = i, None
    while j < end:
        c = t[j]
        if quote:
            if c == "\\" and quote == '"':
                j += 1
            elif c == quote:
                quote = None
        elif c in "'\"":
            quote = c
        elif c == "#" and t[j - 1] in " \t":
            lexer.add(j, end)
            return
        j += 1


class HashLexer(Lexer):
    def __init__(self, text: str, line_start_only: bool = False):
        super().__init__(text)
        self.line_start_only = line_start_only

    def run(self) -> list[Comment]:
        i = 0
        while i < self.n:
            end = self.line_end(i)
            hash_line(self, i, end, self.line_start_only)
            i = end + 1
        return self.found


BLOCK_SCALAR = re.compile(r"^(\s*)(?:-\s+)?(?:([\w.-]+):\s*)?[|>][-+0-9]*\s*(?:#.*)?$")


class YamlLexer(Lexer):
    def run(self) -> list[Comment]:
        lines = self.text.split("\n")
        starts, pos = [], 0
        for line in lines:
            starts.append(pos)
            pos += len(line) + 1
        k = 0
        while k < len(lines):
            line = lines[k]
            hash_line(self, starts[k], starts[k] + len(line), False)
            m = BLOCK_SCALAR.match(line)
            k += 1
            if not m:
                continue
            indent = len(line) - len(line.lstrip())
            first = k
            while k < len(lines) and (not lines[k].strip() or len(lines[k]) - len(lines[k].lstrip()) > indent):
                k += 1
            if m.group(2) == "run" and first < k:
                body_start = starts[first]
                body_end = starts[k - 1] + len(lines[k - 1])
                for c in ShellLexer(self.text[body_start:body_end]).run():
                    self.add(c.start + body_start, c.end + body_start)
        return self.found


def lexer_for(path: str, text: str) -> Lexer | None:
    name = path.rsplit("/", 1)[-1]
    suffix = "." + name.rsplit(".", 1)[-1] if "." in name else ""
    if suffix == ".rs":
        return RustLexer(text)
    if suffix == ".dart":
        return DartLexer(text)
    if suffix in {".js", ".mjs", ".ts", ".jsonc", ".prettierrc", ".fvmrc", ".webmanifest"}:
        return ScriptLexer(text)
    if suffix == ".tsx":
        return ScriptLexer(text, jsx=True)
    if suffix in {".kt", ".kts", ".gradle", ".swift", ".xcconfig", ".c", ".h", ".pbxproj"}:
        return ScriptLexer(text, nested=suffix in {".kt", ".kts", ".swift"})
    if suffix == ".css":
        return CssLexer(text)
    if suffix in {".xml", ".plist", ".storyboard", ".xcscheme", ".html"}:
        return MarkupLexer(text)
    if suffix == ".astro":
        return AstroLexer(text)
    if suffix == ".py":
        return PythonLexer(text)
    if suffix in {".yml", ".yaml"}:
        return YamlLexer(text)
    if suffix in {".toml", ".properties", ".metadata", ".caddy"} or name in {"Caddyfile", "CMakeLists.txt"}:
        return HashLexer(text)
    if name in {".gitignore", ".dockerignore", ".assetsignore", "Dockerfile", "_headers", "_redirects"}:
        return HashLexer(text, line_start_only=True)
    if suffix in {".sh", ".ps1", ".cmd"} or text.startswith("#!/bin/bash") or text.startswith("#!/usr/bin/env bash") or text.startswith("#!/bin/sh"):
        return ShellLexer(text)
    return None


def exempt(path: str, text: str) -> bool:
    if path.startswith(VENDORED):
        return True
    head = text[:400]
    return any(h in head for h in GENERATED_HEADERS)


def tracked() -> list[str]:
    out = subprocess.run(["git", "ls-files"], cwd=ROOT, capture_output=True, text=True, check=True)
    return [
        p for p in out.stdout.splitlines()
        if Path(p).suffix.lower() not in SKIP_SUFFIXES and Path(p).name not in PROSE
    ]


def comments(path: str, text: str) -> list[Comment]:
    lexer = lexer_for(path, text)
    if lexer is None or exempt(path, text):
        return []
    return sorted(set(lexer.run()), key=lambda c: c.start)


def unknown(paths: list[str]) -> list[str]:
    missing = []
    for path in paths:
        full = ROOT / path
        if not full.is_file():
            continue
        try:
            text = full.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        if lexer_for(path, text) is None and not exempt(path, text):
            missing.append(path)
    return missing


def main() -> int:
    paths = tracked()
    failures = 0
    for path in paths:
        full = ROOT / path
        if not full.is_file():
            continue
        try:
            text = full.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        for c in comments(path, text):
            line = text.count("\n", 0, c.start) + 1
            snippet = text[c.start:c.end].splitlines()[0][:100]
            print(f"{path}:{line}: {snippet}")
            failures += 1
    gaps = unknown(paths)
    for path in gaps:
        print(f"{path}: no comment syntax known for this file; teach check_no_comments.py its language")
    if failures or gaps:
        print(f"\n{failures} comments, {len(gaps)} files of unknown language. Code carries no comments: say it in names, types and docs/.")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
